/** Purge each expired issue and its dependent records atomically. */
export async function purgeExpiredIssues(orgId: OrgId, cutoff: IsoTimestamp): Promise<number> {
  const db = getDb();
  const expired = db.select().from(issues).where(and(eq(issues.orgId, orgId), lte(issues.archivedAt, cutoff))).all();
  for (const issue of expired) {
    db.transaction((tx) => {
      const max = tx.select({ value: sql<number | null>"'`max(${issues.number})` }).from(issues)
        .where(and(eq(issues.orgId, orgId), eq(issues.projectId, issue.projectId))).get();
      tx.insert(issueNumbers).values({ orgId, projectId: issue.projectId, highWater: max?.value ?? issue.number })
        .onConflictDoUpdate({ target: issueNumbers.projectId, set: { highWater: sql`max(${issueNumbers.highWater}, ${max?.value ?? issue.number})` } }).run();
      const commentIds = tx.select({ id: comments.id }).from(comments)
        .where(and(eq(comments.orgId, orgId), eq(comments.issueId, issue.id)));
      tx.delete(searchIndex).where(and(eq(searchIndex.orgId, orgId), or(
        and(eq(searchIndex.subjectKind, "issue"), eq(searchIndex.subjectId, issue.id)),
        and(eq(searchIndex.subjectKind, "comment"), inArray(searchIndex.subjectId, commentIds)),
      ))).run();
      const files = tx.select().from(attachments).where(and(eq(attachments.orgId, orgId), eq(attachments.issueId, issue.id))).all();
      const mb = files.reduce((sum, file) => sum + Math.ceil(file.sizeBytes / (1024 * 1024)), 0);
      tx.update(organizationUsage).set({ storageMbUsed: sql`${organizationUsage.storageMbUsed} - ${mb}` }).where(eq(organizationUsage.orgId, orgId)).run();
      tx.delete(attachments).where(and(eq(attachments.orgId, orgId), eq(attachments.issueId, issue.id))).run();
      tx.delete(comments).where(and(eq(comments.orgId, orgId), eq(comments.issueId, issue.id))).run();
      tx.delete(issueLabels).where(and(eq(issueLabels.orgId, orgId), eq(issueLabels.issueId, issue.id))).run();
      tx.delete(issues).where(and(eq(issues.orgId, orgId), eq(issues.id, issue.id))).run();
    });
  }
  return expired.length;
}
